const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define locations: Beira and Manga, Mozambique
  const beira = ee.Geometry.Point([34.8389, -19.8436]);
  const manga = ee.Geometry.Point([34.8167, -20.0000]);
  const region = ee.Geometry.MultiPoint([beira, manga]).buffer(5000); // 5km buffer around both cities

  // Define dates
  const date1 = '2019-03-09';
  const date2 = '2019-03-24';

  // Try VIIRS DNB monthly composite (most reliable for nighttime lights)
  const collection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterBounds(region)
    .select('avg_rad'); // Average radiance band

  // Get March 2019 image
  const marchImg = collection.filter(ee.Filter.date('2019-03-01', '2019-03-31')).first();

  // Check if image exists
  const imgCheck = await new Promise((resolve) => {
    marchImg.getInfo((result, error) => {
      resolve(result !== null && !error);
    });
  });

  if (!imgCheck) {
    console.log('No VIIRS monthly data for March 2019.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Since monthly data doesn't give us daily resolution, let's try daily VIIRS data
  // Use VNP46A2 daily product if available
  const dailyCollection = ee.ImageCollection('NOAA/VIIRS/001/VNP46A2')
    .filterBounds(region)
    .select('DNB_BRDF_Corrected_NTL');

  const img1 = dailyCollection.filter(ee.Filter.date(date1, ee.Date(date1).advance(1, 'day'))).mosaic();
  const img2 = dailyCollection.filter(ee.Filter.date(date2, ee.Date(date2).advance(1, 'day'))).mosaic();

  // Calculate mean nighttime light intensity for both dates
  const stats1Promise = img1.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: region,
    scale: 500,
    maxPixels: 1e9
  }).getInfo();

  const stats2Promise = img2.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: region,
    scale: 500,
    maxPixels: 1e9
  }).getInfo();

  const stats1 = await stats1Promise;
  const stats2 = await stats2Promise;

  const mean1 = stats1.DNB_BRDF_Corrected_NTL_mean;
  const count1 = stats1.DNB_BRDF_Corrected_NTL_count;
  const mean2 = stats2.DNB_BRDF_Corrected_NTL_mean;
  const count2 = stats2.DNB_BRDF_Corrected_NTL_count;

  console.log(`March 9: Mean=${mean1}, Pixels=${count1}`);
  console.log(`March 24: Mean=${mean2}, Pixels=${count2}`);

  // Validation
  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (mean1 === null || mean2 === null || isNaN(mean1) || isNaN(mean2)) {
    console.log('Calculation resulted in null/NaN values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare: Was March 24 lower than March 9?
  if (mean2 < mean1) {
    console.log(`March 24 intensity (${mean2.toFixed(3)}) < March 9 (${mean1.toFixed(3)})`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`March 24 intensity (${mean2.toFixed(3)}) >= March 9 (${mean1.toFixed(3)})`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
